<?php $esc = function($v) { return htmlspecialchars((string)$v, ENT_QUOTES, 'UTF-8'); }; $entry = isset($entry) ? $entry : null; $value = function($name, $default = '') use ($entry) { return $entry ? (isset($entry->$name) ? $entry->$name : $default) : $default; }; ?>
<!DOCTYPE html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><?php include('includes/page-title.php'); ?><link href="<?= base_url(); ?>assets/css/bootstrap.min.css" rel="stylesheet"><link href="<?= base_url(); ?>assets/css/icons.min.css" rel="stylesheet"><link href="<?= base_url(); ?>assets/css/app.min.css" rel="stylesheet"><style>body{background:#f4f6fb}.form-card{margin-top:22px;border:0;border-radius:16px;box-shadow:0 5px 18px rgba(31,41,55,.09)}.section-title{color:#185a9d;border-bottom:1px solid #e8ecf3;padding-bottom:9px;margin:5px 0 18px}</style></head><body><div id="wrapper"><?php include('includes/top-bar.php'); ?><?php include('includes/sidebar.php'); ?><div class="content-page"><div class="content"><div class="container-fluid"><div class="card form-card"><div class="card-body p-4"><div class="d-flex justify-content-between"><div><small class="text-uppercase font-weight-bold text-muted">QMS · <?= $esc($sectionName); ?></small><h3><?= $entry ? 'Edit' : 'Add'; ?> Risk Registry Entry</h3></div><a class="btn btn-light" href="<?= base_url(); ?>Page/risk_registry">Back</a></div><form method="post" action="<?= base_url(); ?>Page/risk_registry_save"><input type="hidden" name="id" value="<?= $entry ? (int)$entry->id : ''; ?>"><h5 class="section-title">Risk Identification</h5><div class="form-row"><div class="form-group col-md-4"><label>Declared Process &amp; Risk Description *</label><textarea class="form-control" rows="5" name="declared_process" required><?= $esc($value('declared_process')); ?></textarea></div><div class="form-group col-md-4"><label>Risk Causes &amp; Consequences</label><textarea class="form-control" rows="5" name="risk_causes_consequences"><?= $esc($value('risk_causes_consequences')); ?></textarea></div><div class="form-group col-md-4"><label>Current Controls</label><textarea class="form-control" rows="5" name="current_controls"><?= $esc($value('current_controls')); ?></textarea></div></div><h5 class="section-title">Risk Analysis &amp; Evaluation</h5><div class="form-row"><div class="form-group col-md-3"><label>Likelihood (L)</label><select class="form-control rating-input" name="likelihood" id="likelihood"><?php for($i=1;$i<=5;$i++): ?><option value="<?= $i; ?>" <?= (int)$value('likelihood',1)===$i?'selected':''; ?>><?= $i; ?></option><?php endfor;?></select></div><div class="form-group col-md-3"><label>Impact (I)</label><select class="form-control rating-input" name="impact" id="impact"><?php for($i=1;$i<=5;$i++): ?><option value="<?= $i; ?>" <?= (int)$value('impact',1)===$i?'selected':''; ?>><?= $i; ?></option><?php endfor;?></select></div><div class="form-group col-md-3"><label>Risk Rating (RR)</label><input class="form-control" id="riskRating" readonly value="<?= (int)$value('risk_rating',1); ?>"></div></div><h5 class="section-title">Risk Treatment &amp; Target Risk Assessment</h5><div class="form-row"><div class="form-group col-md-4"><label>Action / Response</label><textarea class="form-control" rows="3" name="action_response"><?= $esc($value('action_response')); ?></textarea></div><div class="form-group col-md-3"><label>Person / Office Responsible</label><input class="form-control" name="person_responsible" value="<?= $esc($value('person_responsible')); ?>"></div><div class="form-group col-md-2"><label>Target Date</label><input class="form-control" type="date" name="target_date" value="<?= $esc($value('target_date')); ?>"></div><div class="form-group col-md-1"><label>Target L</label><select class="form-control rating-input" name="target_likelihood" id="targetLikelihood"><?php for($i=1;$i<=5;$i++): ?><option value="<?= $i; ?>" <?= (int)$value('target_likelihood',1)===$i?'selected':''; ?>><?= $i; ?></option><?php endfor;?></select></div><div class="form-group col-md-1"><label>Target I</label><select class="form-control rating-input" name="target_impact" id="targetImpact"><?php for($i=1;$i<=5;$i++): ?><option value="<?= $i; ?>" <?= (int)$value('target_impact',1)===$i?'selected':''; ?>><?= $i; ?></option><?php endfor;?></select></div><div class="form-group col-md-1"><label>Target RR</label><input class="form-control" id="targetRiskRating" readonly value="<?= (int)$value('target_risk_rating',1); ?>"></div></div><button class="btn btn-primary" type="submit"><i class="mdi mdi-content-save"></i> Save Entry</button></form></div></div></div></div><?php include('includes/footer.php'); ?></div></div><script src="<?= base_url(); ?>assets/js/vendor.min.js"></script><script>function rates(){riskRating.value=likelihood.value*impact.value;targetRiskRating.value=targetLikelihood.value*targetImpact.value}document.querySelectorAll('.rating-input').forEach(x=>x.addEventListener('change',rates));</script></body></html>
